FeatureScript 3112;
import(path : "onshape/std/geometry.fs", version : "3112.0");

// Fixture batch 165: variable fillets with radii at points along the edge. Generated by tools/fixtures/gen-batch-165.mjs; do not edit.
// Each case builds its geometry at the origin and may return a map of values to check.

// The fillet's radius along the block's top edge (y = 20, z = 10, x from 0 to 40), every 2 mm: a circular fillet
// between the perpendicular top and side lies r(sqrt 2 - 1) from the edge along their bisector. Rounded to 1e-6.
function radiusProbe(context is Context, faces is Query) returns array
{
    var out = [];
    for (var i = 0; i <= 20; i += 1)
    {
        const x = 2 * i;
        const ray = line(vector(x, 20, 10) * millimeter, vector(0, -1, -1) / sqrt(2));
        const d = evDistance(context, { "side0" : faces, "side1" : ray });
        const p = d.sides[0].point;
        const along = norm(p - vector(x, 20, 10) * millimeter);
        out = append(out, roundToPrecision(along / millimeter / (sqrt(2) - 1), 6));
    }
    return out;
}

// fillet: a variable fillet, 2 at both ends and 4 halfway, smooth
export function c001(context is Context, id is Id)
{
    const baseSketch = newSketchOnPlane(context, id + "baseSketch", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skRectangle(baseSketch, "rect1", { "firstCorner" : vector(0, 0) * millimeter, "secondCorner" : vector(40, 20) * millimeter });
    skSolve(baseSketch);
    extrude(context, id + "base", { "entities" : qSketchRegion(id + "baseSketch"), "endBound" : BoundingType.BLIND, "depth" : 10 * millimeter });
    fillet(context, id + "fillet1", { "entities" : qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), EntityType.EDGE), vector(20, 20, 10) * millimeter), "radius" : 2 * millimeter, "isVariable" : true, "crossSection" : FilletCrossSection.CIRCULAR, "vertexSettings" : [{ "vertex" : qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), EntityType.VERTEX), vector(0, 20, 10) * millimeter), "vertexRadius" : 2 * millimeter }, { "vertex" : qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), EntityType.VERTEX), vector(40, 20, 10) * millimeter), "vertexRadius" : 2 * millimeter }], "pointOnEdgeSettings" : [{ "edge" : qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), EntityType.EDGE), vector(20, 20, 10) * millimeter), "edgeParameter" : 0.5, "pointOnEdgeRadius" : 4 * millimeter }], "smoothTransition" : true });
    return { "radii" : radiusProbe(context, qCreatedBy(id + "fillet1", EntityType.FACE)) };
}

